    },
    {
      "role": "user",
      "content": {{ JSON.stringify('Tender: ' + ($json.description || '') + '\n\nBuyer: ' + ($json.buyer || '') + '\n\nSearch Results:\n' + ($json.search_results_text || '')) }}
    }
  ]
}

