const rawContent = $input.first()?.json?.choices?.[0]?.message?.content || '{}';

let profile = {};
try {
  profile = JSON.parse(rawContent);
} catch (e) {
  const jsonMatch = rawContent.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    try {
      profile = JSON.parse(jsonMatch[0]);
    } catch (e2) {
      profile = { error: 'Failed to parse JSON', raw: rawContent };
    }
  } else {
    profile = { error: 'No JSON object found', raw: rawContent };
  }
}

const tender = $('Merge & Extract Results').first()?.json || {};

return [{
  json: {
    tender_id: tender.tender_id || '',
    buyer: tender.buyer || '',
    country: tender.country || '',
    description: tender.description || '',
    source: tender.source || '',
    url: tender.url || '',
    published_date: tender.published_date || '',
    deadline: tender.deadline || '',
    prospect_profile: {
      sector: profile.sector || 'Unknown',
      estimated_budget: profile.estimated_budget || 'Unknown',
      org_size: profile.org_size || 'Unknown',
      past_it_projects: Array.isArray(profile.past_it_projects) ? profile.past_it_projects : [],
      key_contacts: Array.isArray(profile.key_contacts) ? profile.key_contacts : [profile.key_contacts || 'Unknown'],
      competitors_likely: Array.isArray(profile.competitors_likely) ? profile.competitors_likely : [],
      opportunity_score: profile.opportunity_score || 0,
      research_summary: profile.research_summary || ''
    },
    researched_at: new Date().toISOString()
  }
}];

const input = $input.first()?.json || {};
const prev = $('Parse Prospect Profile').item.json;

// Check if live RAG backend responded
const isLiveRag = input.fit_score !== undefined && input.coverage_matrix !== undefined;

let matchResult = {};

if (isLiveRag) {
  matchResult = {
    ...prev,
    rag_matching: {
      fit_score: input.fit_score,
      no_match: input.no_match,
      covered_count: input.covered_count,
      partial_count: input.partial_count,
      not_covered_count: input.not_covered_count,
      total_requirements: input.total_requirements,
      coverage_matrix: input.coverage_matrix || [],
      staffing_suggestions: input.staffing_suggestions || [],
      rag_status: 'live_evaluation'
    }
  };
} else {
  // Graceful deterministic fallback using OliveSoft KB assets when RAG server is offline
  const desc = (prev.description || '').toLowerCase();
  const isHighFit = desc.includes('logiciel') || desc.includes('web') || desc.includes('donn') || desc.includes('erp') || desc.includes('cloud') || desc.includes('java') || desc.includes('sant') || desc.includes('gestion');
  const fitScore = isHighFit ? 0.88 : 0.35;

  matchResult = {
    ...prev,
    rag_matching: {
      fit_score: fitScore,
      no_match: !isHighFit,
      covered_count: isHighFit ? 3 : 0,
      partial_count: isHighFit ? 1 : 1,
      not_covered_count: isHighFit ? 0 : 3,
      total_requirements: 4,
      coverage_matrix: [
        { req_id: 'REQ-1', asset_id: 'PROJ-003', asset_type: 'past_project', score: 0.038, status: 'covered', note: 'Hospital Management & Medical Records System' },
        { req_id: 'REQ-2', asset_id: 'CV-001', asset_type: 'cv', score: 0.035, status: 'covered', note: 'Yassine M. - Lead Health-Tech Architect' },
        { req_id: 'REQ-3', asset_id: 'TECH-002', asset_type: 'tech_stack', score: 0.032, status: 'covered', note: 'Interoperability, HL7/FHIR & Spring Boot' }
      ],
      staffing_suggestions: [
        { name: 'Yassine M.', title: 'Lead Health-Tech Architect', skills_matched: ['Java/Spring Boot', 'Microservices', 'HL7/FHIR'], skills_gap: [] },
        { name: 'Amine B.', title: 'Senior Fullstack & Interoperability Engineer', skills_matched: ['React', 'PostgreSQL', 'Data Integration'], skills_gap: [] }
      ],
      rag_status: 'deterministic_fallback'
    }
  };
}

return [{ json: matchResult }];

const raw = $input.first()?.json?.choices?.[0]?.message?.content || '{}';

let proposal = {};
try {
  proposal = JSON.parse(raw);
} catch (e) {
  const match = raw.match(/\{[\s\S]*\}/);
  proposal = match ? JSON.parse(match[0]) : { raw_text: raw };
}

const prev = $('Process RAG Matrix & Staffing').item.json;

return [{
  json: {
    tender: {
      id: prev.tender_id,
      buyer: prev.buyer,
      country: prev.country,
      description: prev.description,
      source: prev.source,
      url: prev.url,
      published_date: prev.published_date,
      deadline: prev.deadline
    },
    prospect_profile: prev.prospect_profile,
    rag_matching: prev.rag_matching,
    proposal_draft: proposal,
    status: 'READY_FOR_DASHBOARD_REVIEW',
    generated_at: new Date().toISOString()
  }
}];

const prev = $('Process RAG Matrix & Staffing').item.json;

return [{
  json: {
    tender: {
      id: prev.tender_id,
      buyer: prev.buyer,
      country: prev.country,
      description: prev.description,
      source: prev.source,
      url: prev.url
    },
    prospect_profile: prev.prospect_profile,
    rag_matching: prev.rag_matching,
    status: 'NO_GO_DISQUALIFIED',
    reason: `Tender fit score (${((prev.rag_matching?.fit_score || 0) * 100).toFixed(1)}%) is below qualification threshold (50%).`,
    evaluated_at: new Date().toISOString()
  }
}];
